import {STORAGE_KEY,roomKey,emptyRules,owns,decision,selected,setRule,groupState,overlap,conflicts,eventClock,isLive,sortActivities,filterActivities,loadState,validateData} from './domain.js';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const formatDay=(d,short=false)=>new Intl.DateTimeFormat('es-CL',{weekday:short?'short':'long',day:'numeric',month:short?undefined:'long',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));
let data,lookup,state,readOnly=false,tab='now',day,query='',room='',level='',aux=true,layout='room',exploring=false,exploreDate,exploreTime='09:00',conflictOnly=false,dialogContext=null,undo=null,toastTimer,waitingWorker;
const opened=new Set(),scrolls={};let conflictInfo={pairs:[],ids:new Set(),unknown:[]};
const badge=l=>`<span class="badge level${l}">Nivel ${l}</span>`;
const levels=a=>a.levels.length?a.levels.map(badge).join(''):'<span class="badge">Sin nivel informado</span>';
const timeRange=a=>a.start&&a.end?`${a.start}–${a.end}`:'Horario no informado';
const clock=()=>exploring?{date:exploreDate,time:exploreTime}:eventClock();
function showToast(message,canUndo=false){clearTimeout(toastTimer);$('#toast').hidden=false;$('#toast').innerHTML=esc(message)+(canUndo?' <button data-action="undo">Deshacer</button>':'');toastTimer=setTimeout(()=>$('#toast').hidden=true,canUndo?9000:6500);}
function save(){if(readOnly){showToast('Los cambios se mantienen solo en esta sesión. La ruta guardada no se ha sobrescrito.');return false;}try{state.dataVersion=data.meta.version;state.signatures=Object.fromEntries(data.activities.filter(a=>selected(a,state.rules)).map(a=>[a.id,`${a.date}|${a.start}|${a.end}|${a.roomId}`]));localStorage.setItem(STORAGE_KEY,JSON.stringify(state));return true;}catch{showToast('No se pudo guardar. Conserva esta pestaña abierta; tu ruta está solo en esta sesión.');return false;}}
function mutate(fn,message){undo=structuredClone(state.rules);state.rules=fn(state.rules);const saved=save();render();if(dialogContext)renderDialog();if(message&&saved)showToast(message,true);}
function row(a,{showRoom=true,live=false}={}){const d=decision(a,state.rules),c=conflictInfo.ids.has(a.id);return `<article class="activity ${d.selected?'selected':''} ${c?'conflicted':''} ${a.auxiliary?'auxiliary':''}" data-activity="${a.id}"><div class="timecell">${esc(a.start??'—')}<span>${esc(a.end??'Por informar')}</span></div><div><button class="activity-title" data-detail="${a.id}">${esc(a.title)}</button><div class="activity-meta">${showRoom?`${esc(lookup.rooms[a.roomId].name)}${a.speaker?' · ':''}`:''}${esc(a.speaker??'')}</div><div class="activity-tags">${live?'<span class="badge live">Ahora</span>':''}${levels(a)}${c?'<span class="badge conflict">Coincide con tu ruta</span>':''}${!a.start?'<span class="badge">Horario pendiente</span>':''}</div>${d.source==='individual'?`<div class="exception">${d.selected?'Elección individual':'Excluida de mi ruta'}</div>`:d.selected?`<div class="exception">Incluida por ${d.source==='block'?'bloque':'sala'}</div>`:''}</div><button class="pick" data-pick="${a.id}" aria-pressed="${d.selected}" aria-label="${d.selected?'Quitar de':'Agregar a'} mi ruta: ${esc(a.title)}">${d.selected?'✓':'+'}</button></article>`;}
function toolbar(){
 if(tab==='route')return '<div class="optionsbar"><span class="muted">Tus elecciones de todos los días</span><button class="textbutton" data-action="clear-dialog">Restablecer ruta</button></div>';
 const dates=`<div class="daybar" aria-label="Día del programa">${data.meta.dates.map(d=>`<button class="daybutton ${day===d?'active':''}" data-day="${d}" aria-pressed="${day===d}"><span>${formatDay(d,true).replace(/\s*\d+.*$/,'')}</span><strong>${+d.slice(-2)}</strong>${d===data.meta.dates[0]?'<span class="pre">Precongreso</span>':''}</button>`).join('')}</div>`;
 const rooms=data.rooms.filter(r=>data.activities.some(a=>a.roomId===r.id&&a.date===(tab==='now'?clock().date:day)));
 const filters=`<div class="filters"><label class="searchbox"><span class="sr-only">Buscar charla, ponente o tema</span><input type="search" id="search" placeholder="Buscar charla, ponente o tema" value="${esc(query)}"></label><select class="filterselect" id="roomFilter" aria-label="Filtrar por sala"><option value="">Todas las salas</option>${rooms.map(r=>`<option value="${r.id}" ${room===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select><select class="filterselect" id="levelFilter" aria-label="Filtrar por nivel"><option value="">Todos los niveles</option>${[1,2,3].map(l=>`<option value="${l}" ${level===String(l)?'selected':''}>Nivel ${l}</option>`).join('')}<option value="none" ${level==='none'?'selected':''}>Sin nivel informado</option></select></div><div class="optionsbar"><label class="switchlabel"><input type="checkbox" id="auxToggle" ${aux?'checked':''}> Pausas, preguntas y otras actividades</label>${tab==='program'?`<div class="segmented" aria-label="Organización del programa"><button data-layout="room" class="${layout==='room'?'active':''}" aria-pressed="${layout==='room'}">Por sala</button><button data-layout="time" class="${layout==='time'?'active':''}" aria-pressed="${layout==='time'}">Por hora</button></div>`:''}${query||room||level||!aux?'<button class="textbutton" data-action="clear-filters">Limpiar filtros</button>':''}</div>`;
 const c=clock(),nowControls=`<div class="now-control"><span class="now-time">${c.time}</span><span class="muted">${formatDay(c.date)} · Chile</span><button class="textbutton" data-action="explore">${exploring?'Volver a ahora':'Explorar otro horario'}</button></div>${exploring?`<div class="explore"><strong class="badge">MODO EXPLORACIÓN</strong><label>Día <select id="exploreDate">${data.meta.dates.map(d=>`<option value="${d}" ${d===exploreDate?'selected':''}>${formatDay(d)}</option>`).join('')}</select></label><label>Hora <input type="time" id="exploreTime" value="${exploreTime}" required></label></div>`:''}`;
 return (tab==='now'?nowControls:dates)+filters;
}
function empty(title,message,action=true){return `<div class="empty"><div class="emptyicon" aria-hidden="true">◷</div><h2>${esc(title)}</h2><p>${esc(message)}</p>${action?'<button class="primary" data-tab="program">Explorar el programa</button>':''}</div>`;}
function renderProgram(){
 const visible=filterActivities(data.activities,{day,room,level,q:query,aux},lookup),set=new Set(visible.map(a=>a.id));
 if(!visible.length)return empty('Sin resultados','Prueba con otro día o limpia los filtros.',false);
 const html=`<div class="resultline"><span>${visible.length} de ${data.activities.filter(a=>a.date===day).length} actividades del día</span><div class="legend">${[1,2,3].map(badge).join('')}</div></div>`;
 if(layout==='time'){const starts=[...new Set(visible.map(a=>a.start??'Por informar'))].sort();return html+starts.map(t=>`<section class="timeline-group"><h2 class="timeline-title">${t==='Por informar'?'Horario no informado':`${t} · Inicio de actividades`}</h2>${visible.filter(a=>(a.start??'Por informar')===t).sort(sortActivities).map(a=>row(a)).join('')}</section>`).join('');}
 return html+data.rooms.map((r,ri)=>{const bs=data.blocks.filter(b=>b.date===day&&b.roomId===r.id&&visible.some(a=>a.blockId===b.id));if(!bs.length)return '';const all=data.activities.filter(a=>a.date===day&&a.roomId===r.id),gs=groupState(all,state.rules);return `<section class="room-section"><div class="room-header"><div class="room-title"><span class="room-number">${String(ri+1).padStart(2,'0')}</span><div><h2>${esc(r.name)}</h2><small>${gs.count} de ${gs.total} en tu ruta · ${gs.state==='mixed'?'Selección parcial':gs.state==='all'?'Sala completa':'Sin selección'}</small></div></div><button class="groupbutton" data-group="room" data-key="${r.id}">Elegir sala</button></div>${bs.map((b,i)=>{const ba=data.activities.filter(a=>a.blockId===b.id),gs=groupState(ba,state.rules);return `<details class="block" data-block="${b.id}" ${opened.has(b.id)||query||i===0&&!opened.size?'open':''}><summary class="block-summary"><div class="block-title"><strong>${esc(b.title)}</strong><small>${esc(b.start??'Horario pendiente')}${b.end?'–'+b.end:''} · ${ba.length} actividades${gs.count?' · '+gs.count+' elegidas':''}</small></div><span class="badge">${gs.state==='mixed'?'Parcial':gs.state==='all'?'Completo':ba.length}</span><span class="chevron" aria-hidden="true">⌄</span></summary><div class="block-controls"><span>Todo el bloque · ${ba.length} actividades</span><button class="textbutton" data-group="block" data-key="${b.id}">Elegir bloque</button></div>${ba.filter(a=>set.has(a.id)).sort(sortActivities).map(a=>row(a,{showRoom:false})).join('')}</details>`}).join('')}</section>`}).join('');
}
function renderNow(){
 const c=clock(),relevant=filterActivities(data.activities,{day:c.date,room,level,q:query,aux},lookup);
 if(!data.meta.dates.includes(c.date)){const next=data.activities.filter(a=>a.date>c.date).sort(sortActivities)[0];return empty(next?'El programa aún no comienza':'Fuera de las jornadas del programa',next?`La próxima jornada es el ${formatDay(next.date)}. Puedes preparar tu ruta o explorar un horario.`:'Consulta el programa y tu ruta guardada. No se muestran actividades pasadas como si estuvieran ocurriendo.');}
 const live=relevant.filter(a=>isLive(a,c)),html=`<div class="resultline"><span>${live.length} actividades en curso${query||room||level?' con tus filtros':''}</span><span>Actualizado cada minuto</span></div>`;
 const sections=data.rooms.map(r=>{const current=live.filter(a=>a.roomId===r.id),future=relevant.filter(a=>a.roomId===r.id&&a.start&&a.start>c.time).sort(sortActivities),next=future[0],unknown=relevant.filter(a=>a.roomId===r.id&&!a.start);if(!current.length&&!next&&!unknown.length)return '';return `<section class="room-section"><div class="room-header"><h2>${esc(r.name)}</h2><button class="groupbutton" data-action="go-room" data-key="${r.id}">Ver sala</button></div><div class="block">${current.length?current.map(a=>row(a,{showRoom:false,live:true})).join(''):'<p class="details-note" style="padding:8px 16px">Sin actividad en curso con estos filtros.</p>'}${next?`<h3 class="timeline-title">Después · ${next.start}</h3>${row(next,{showRoom:false})}`:''}${unknown.map(a=>row(a,{showRoom:false})).join('')}</div></section>`;}).join('');return html+(sections||empty('Sin actividades en este horario','Puedes explorar otro horario o consultar el programa.'));
}
function renderRoute(){
 const chosen=data.activities.filter(a=>selected(a,state.rules)).sort(sortActivities);if(!chosen.length)return empty('Tu ruta empieza con una elección','Elige una sala completa, un bloque o una charla. Después puedes ajustar las excepciones.');
 let html=`<div class="statgrid"><div><strong>${chosen.length}</strong><span>actividades elegidas</span></div><div><strong>${new Set(chosen.map(a=>a.date)).size}</strong><span>días en tu ruta</span></div><div><strong>${conflictInfo.pairs.length}</strong><span>coincidencias</span></div></div>`;
 if(conflictInfo.pairs.length)html+=`<div class="conflict-note"><strong>Hay actividades que coinciden en horario.</strong> Se conservan todas tus elecciones.<div class="buttonrow"><button class="secondary" data-action="conflicts">Revisar ${conflictInfo.pairs.length} coincidencias</button><button class="textbutton" data-action="conflict-filter">${conflictOnly?'Ver toda mi ruta':'Mostrar solo conflictos'}</button></div></div>`;
 if(conflictInfo.unknown.length)html+=`<div class="notice">${conflictInfo.unknown.length} actividades tienen horario no informado. No es posible comprobar todos sus conflictos.</div>`;
 const list=conflictOnly?chosen.filter(a=>conflictInfo.ids.has(a.id)):chosen;
 for(const d of data.meta.dates){const daily=list.filter(a=>a.date===d);if(!daily.length)continue;html+=`<h2 class="route-day">${formatDay(d)}</h2><div class="block">${daily.map((a,i)=>`${i&&a.roomId!==daily[i-1].roomId?'<div class="transfer">Cambio de sala · tiempo de traslado no calculado</div>':''}${row(a)}`).join('')}</div>`;}
 return html;
}
function render(onlyContent=false){if(!data)return;conflictInfo=conflicts(data.activities,state.rules);const total=data.activities.filter(a=>selected(a,state.rules)).length;if(!conflictInfo.pairs.length)conflictOnly=false;
 $('#routeCount').textContent=total;$('#routeSummary').innerHTML=`<strong>${total}</strong> en tu ruta${conflictInfo.pairs.length?`<br><span>${conflictInfo.pairs.length} coincidencias por revisar</span>`:''}`;
 document.querySelectorAll('#navigation [data-tab]').forEach(b=>{const active=b.dataset.tab===tab;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});
 $('#viewTitle').textContent={now:'¿Qué está pasando?',program:'Programa',route:'Mi Ruta'}[tab];$('#viewSubtitle').textContent={now:'Lo que ocurre ahora, sala por sala.',program:'Todas las salas. Tu próxima elección.',route:'Tus elecciones, en orden. A tu ritmo.'}[tab];if(!onlyContent)$('#toolbar').innerHTML=toolbar();
 $('#content').innerHTML=(data.meta.auditStatus!=='reviewed'?'<div class="notice">Programa en revisión. Consulta la fuente de cada actividad para confirmar los detalles.</div>':'')+(tab==='now'?renderNow():tab==='program'?renderProgram():renderRoute());
 document.querySelectorAll('details[data-block]').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)opened.add(d.dataset.block);else opened.delete(d.dataset.block)}));
}
function setTab(next){if(!['now','program','route'].includes(next))return;scrolls[tab]=window.scrollY;tab=next;render();window.scrollTo({top:scrolls[tab]??0,behavior:'instant'});}
function openDialog(context){dialogContext=context;renderDialog();if(!$('#detail').open)$('#detail').showModal();}
function groupActivities(ctx){return data.activities.filter(a=>ctx.scope==='block'?a.blockId===ctx.key:a.roomId===ctx.key&&(ctx.allDays||a.date===ctx.date));}
function renderDialog(){
 const ctx=dialogContext;if(!ctx)return;let title='',html='';
 if(ctx.kind==='detail'){
 const a=lookup.activities[ctx.id],d=decision(a,state.rules);title='Actividad';html=`<h3 class="detail-title">${esc(a.title)}</h3><div class="legend">${levels(a)}</div><dl class="details-grid"><dt>Horario</dt><dd>${formatDay(a.date)}<br>${timeRange(a)}</dd><dt>Sala</dt><dd>${esc(lookup.rooms[a.roomId].name)}</dd><dt>Bloque</dt><dd>${esc(lookup.blocks[a.blockId].title)}</dd>${a.speaker?`<dt>${a.speakerRole==='moderator'?'Modera':'Participa'}</dt><dd>${esc(a.speaker)}</dd>`:''}<dt>Mi Ruta</dt><dd>${d.selected?'Incluida':'No incluida'}${d.source!=='none'?` · decisión ${d.source==='individual'?'individual':d.source==='block'?'del bloque':'de la sala'}`:''}</dd></dl>${a.note?`<div class="notice">${esc(a.note)}</div>`:''}<div class="buttonrow"><button class="primary" data-pick="${a.id}">${d.selected?'Quitar de mi ruta':'Agregar a mi ruta'}</button>${owns(state.rules.activities,a.id)?`<button class="secondary" data-inherit="${a.id}">Usar selección del grupo</button>`:''}</div><div class="detail-section"><h3>En paralelo</h3><p class="details-note">Otras actividades cuyos horarios se superponen. Tus elecciones se conservan.</p>${a.start&&a.end?data.activities.filter(b=>overlap(a,b)).sort(sortActivities).map(b=>row(b)).join('')||'<p class="details-note">No hay otras actividades en este intervalo.</p>':'<p class="details-note">El horario no está informado; no se pueden calcular coincidencias.</p>'}</div><div class="detail-section"><a href="./programa-2026.pdf#page=${a.source.page}" target="_blank" rel="noopener">Ver programa original · página ${a.source.page}</a><p class="details-note">${esc(a.source.document)} · ${a.verification==='reviewed'?'Registro contrastado con el PDF':'Revisión pendiente'}${a.source.additionalPages?.length?' · También figura en páginas '+a.source.additionalPages.join(', '):''}</p></div>`;
 }else if(ctx.kind==='group'){
 title=ctx.scope==='room'?'Elegir una sala':'Elegir un bloque';const items=groupActivities(ctx),gs=groupState(items,state.rules),name=ctx.scope==='room'?lookup.rooms[ctx.key].name:lookup.blocks[ctx.key].title,specific=items.filter(a=>owns(state.rules.activities,a.id)).length;html=`<h3 class="detail-title">${esc(name)}</h3><p class="details-note">${ctx.allDays?'Todos los días de esta sala':formatDay(ctx.date)}</p>${ctx.scope==='room'?`<label class="switchlabel"><input type="checkbox" id="allDays" ${ctx.allDays?'checked':''}> Esta sala durante todo el congreso</label>`:''}<div class="rulebox">${items.length} actividades en el ámbito completo, incluso las ocultas por filtros.<br><strong>${gs.count} elegidas · ${specific} decisiones individuales.</strong><br>Se conservan las excepciones de charlas${ctx.scope==='room'?' y bloques':''}.</div><div class="buttonrow"><button class="primary" data-group-rule="include">Incluir ${ctx.scope==='room'?'sala':'bloque'}</button><button class="secondary" data-group-rule="exclude">Excluir ${ctx.scope==='room'?'sala':'bloque'}</button></div><button class="textbutton" data-group-rule="inherit">${ctx.scope==='block'?'Usar la selección de la sala':'Quitar la regla de la sala'}</button><div class="detail-section"><h3>Restablecer excepciones</h3><p class="details-note">Borra las decisiones individuales${ctx.scope==='room'?' y de bloques':''} de este ámbito. Las actividades volverán a seguir la regla del grupo.</p><button class="secondary" data-group-rule="reset">Restablecer excepciones del grupo</button></div>`;
 }else if(ctx.kind==='conflicts'){
 title='Coincidencias de horario';html=`<p class="details-note">Cada par comparte tiempo. Puedes conservarlo o quitar una elección.</p>${conflictInfo.pairs.map(p=>{const a=lookup.activities[p.a],b=lookup.activities[p.b];return `<div class="conflict-pair"><strong>${formatDay(a.date)} · ${p.minutes} min superpuestos</strong>${row(a)}${row(b)}</div>`}).join('')||'<p>No quedan coincidencias.</p>'}`;
 }else if(ctx.kind==='clear'){
 title='Restablecer mi ruta';html='<p class="details-note">Se borrarán todas las reglas de salas, bloques y charlas guardadas en este dispositivo. Podrás deshacerlo inmediatamente.</p><button class="primary" data-action="clear-route">Borrar selecciones y excepciones</button>';
 }else{
 title='Sobre tu agenda';html=`<h3 class="detail-title">Congreso 2.0</h3><p class="details-note">Agenda personal independiente para el Congreso Chileno de Radiología 2026. No reemplaza los avisos de la organización.</p><div class="statgrid"><div><strong>${data.activities.length}</strong><span>actividades</span></div><div><strong>${data.blocks.length}</strong><span>bloques</span></div><div><strong>${data.meta.sourcePages}</strong><span>páginas de fuente</span></div></div><h3>Datos y fuente</h3><p class="details-note">Versión ${esc(data.meta.version)}. Basada en el HTML y PDF que proporcionaste. Cada actividad enlaza su página. ${esc(data.meta.auditSummary??'Revisión de la fuente en curso.')}</p><div class="buttonrow"><a class="secondary" href="./programa-2026.pdf" target="_blank" rel="noopener">Abrir PDF</a><a class="secondary" href="./audit.html" target="_blank" rel="noopener">Ver auditoría</a><a class="secondary" href="https://congresochilenoradiologia.cl/programa/" target="_blank" rel="noopener">Sitio oficial</a></div><div class="detail-section"><h3>Instalar en tu teléfono</h3><p class="details-note"><strong>iPhone · Safari:</strong> abre Compartir y elige «Agregar a inicio».<br><strong>Android · Chrome:</strong> abre el menú y elige «Instalar app» o «Agregar a pantalla principal» cuando esté disponible.</p><p class="details-note">Tu ruta se guarda solo en este navegador y dispositivo. No se sincroniza. Borrar los datos del navegador elimina esas elecciones. Las selecciones de un archivo HTML abierto anteriormente no se trasladan entre direcciones distintas.</p><p class="details-note">${navigator.serviceWorker?.controller?'La agenda está preparada para consultas sin conexión tras su primera carga. El PDF se abre por separado.':'La disponibilidad sin conexión se prepara al cargar la app por HTTPS.'}</p><p class="details-note">Si ves un aviso de actualización, puedes aplicarla conservando tu ruta.</p></div>`;
 }
 $('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=html;
}
document.addEventListener('click',e=>{
 const el=e.target.closest('button');if(!el||!data)return;
 if(el.dataset.tab){setTab(el.dataset.tab);return;}
 if(el.dataset.day){day=el.dataset.day;room='';opened.clear();render();return;}
 if(el.dataset.layout){layout=el.dataset.layout;render();return;}
 if(el.dataset.pick){const a=lookup.activities[el.dataset.pick];if(a)mutate(r=>setRule(r,'activities',a.id,!selected(a,r)),selected(a,state.rules)?'Actividad excluida de tu ruta.':'Actividad agregada a tu ruta.');return;}
 if(el.dataset.inherit){mutate(r=>setRule(r,'activities',el.dataset.inherit,undefined),'La actividad vuelve a seguir su grupo.');return;}
 if(el.dataset.detail){openDialog({kind:'detail',id:el.dataset.detail});return;}
 if(el.dataset.group){openDialog({kind:'group',scope:el.dataset.group,key:el.dataset.key,date:day,allDays:false});return;}
 if(el.dataset.groupRule){const ctx=dialogContext;if(ctx?.kind!=='group')return;const mode=el.dataset.groupRule,items=groupActivities(ctx);mutate(r=>{let next=structuredClone(r);if(mode==='reset'){items.forEach(a=>{delete next.activities[a.id];if(ctx.scope==='room')delete next.blocks[a.blockId]});}else{const val=mode==='include'?true:mode==='exclude'?false:undefined,keys=ctx.scope==='block'?[ctx.key]:[...new Set(items.map(roomKey))];keys.forEach(k=>next=setRule(next,ctx.scope==='block'?'blocks':'rooms',k,val));}return next;},mode==='reset'?'Excepciones restablecidas.':'Regla actualizada; se conservaron las excepciones.');return;}
 const action=el.dataset.action;
 if(action==='undo'&&undo){const prior=undo;undo=null;state.rules=prior;save();render();if(dialogContext)renderDialog();showToast('Cambio deshecho.');}
 if(action==='clear-filters'){query='';room='';level='';aux=true;render();}
 if(action==='explore'){exploring=!exploring;if(exploring){const real=eventClock();exploreDate=data.meta.dates.includes(real.date)?real.date:day;exploreTime=data.meta.dates.includes(real.date)?real.time:'09:00';}room='';render();}
 if(action==='go-room'){day=clock().date;room=el.dataset.key;setTab('program');}
 if(action==='conflicts')openDialog({kind:'conflicts'});
 if(action==='conflict-filter'){conflictOnly=!conflictOnly;render();}
 if(action==='clear-dialog')openDialog({kind:'clear'});
 if(action==='clear-route'){mutate(()=>emptyRules(),'Ruta restablecida.');$('#detail').close();}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;render(true);}});
document.addEventListener('change',e=>{const id=e.target.id;if(id==='roomFilter')room=e.target.value;if(id==='levelFilter')level=e.target.value;if(id==='auxToggle')aux=e.target.checked;if(id==='exploreDate'){exploreDate=e.target.value;room='';}if(id==='exploreTime'){if(!e.target.value)return;exploreTime=e.target.value;}if(id==='allDays'&&dialogContext?.kind==='group'){dialogContext.allDays=e.target.checked;renderDialog();return;}if(['roomFilter','levelFilter','auxToggle','exploreDate','exploreTime'].includes(id))render();});
$('#closeDetail').addEventListener('click',()=>$('#detail').close());$('#detail').addEventListener('close',()=>dialogContext=null);$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)e.target.close();}});$('#infoButton').addEventListener('click',()=>data&&openDialog({kind:'info'}));
function connection(){const offline=!navigator.onLine;$('#connection').hidden=!offline;$('#connection').textContent='Sin conexión · usando el programa guardado en este dispositivo.';}
window.addEventListener('online',connection);window.addEventListener('offline',connection);connection();
async function init(){try{
 const response=await fetch('./agenda.json');if(!response.ok)throw Error('No se pudo cargar el programa.');data=await response.json();if(validateData(data).length)throw Error('El programa contiene datos inconsistentes.');lookup={rooms:Object.fromEntries(data.rooms.map(r=>[r.id,r])),blocks:Object.fromEntries(data.blocks.map(b=>[b.id,b])),activities:Object.fromEntries(data.activities.map(a=>[a.id,a]))};const today=eventClock().date;day=data.meta.dates.includes(today)?today:data.meta.dates[0];exploreDate=day;
 let raw=null,legacy=null;try{raw=localStorage.getItem(STORAGE_KEY);legacy=localStorage.getItem('cchr2026-picks-v3');}catch{readOnly=true;showToast('El navegador no permite guardar la ruta; se mantendrá solo durante esta sesión.');}
 const loaded=loadState(raw,data,legacy);state=loaded.state;readOnly=readOnly||loaded.readOnly;render();if(loaded.warnings.length)showToast(loaded.warnings.join(' '));document.body.dataset.ready='true';
 setInterval(()=>{if(!document.hidden&&tab==='now'&&!exploring&&!$('#detail').open&&document.activeElement?.tagName!=='INPUT')render();},60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&tab==='now'&&!exploring&&!$('#detail').open)render();});registerTools();await registerOffline();
 }catch(err){$('#content').innerHTML=empty('No pudimos abrir el programa','Comprueba tu conexión y vuelve a cargar la página. Tus elecciones guardadas no se han borrado.',false)+'<button class="primary" id="retry">Volver a intentar</button>';$('#retry').onclick=()=>location.reload();console.error(err);}}
async function registerOffline(){if(!('serviceWorker'in navigator)||!window.isSecureContext)return;try{const r=await navigator.serviceWorker.register('./sw.js'),show=w=>{waitingWorker=w;$('#update').hidden=false;};if(r.waiting)show(r.waiting);r.addEventListener('updatefound',()=>{const w=r.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)show(w)});});$('#applyUpdate').onclick=()=>{if(save())waitingWorker?.postMessage({type:'ACTIVATE'});};let reloading=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(waitingWorker&&!reloading){reloading=true;location.reload();}});}catch{showToast('La agenda funciona, pero no pudo prepararse el uso sin conexión.');}}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController(),tools=[{name:'read_congress_route',description:'Leer las actividades elegidas y sus conflictos sin modificar la ruta.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){return {activities:data.activities.filter(a=>selected(a,state.rules)).map(a=>({id:a.id,title:a.title,date:a.date,start:a.start,end:a.end})),conflicts:conflicts(data.activities,state.rules).pairs};}},{name:'set_congress_activity_selection',description:'Incluir o excluir actividades por ID en la misma ruta local visible, conservando otras elecciones.',inputSchema:{type:'object',properties:{ids:{type:'array',items:{type:'string'},minItems:1,maxItems:100},selected:{type:'boolean'}},required:['ids','selected'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!Array.isArray(input.ids)||!input.ids.length||input.ids.length>100||typeof input.selected!=='boolean'||input.ids.some(id=>typeof id!=='string'||!lookup.activities[id]))throw Error('IDs o selección inválidos.');mutate(r=>input.ids.reduce((x,id)=>setRule(x,'activities',id,input.selected),r));return {updated:input.ids.length,selected:input.selected,conflicts:conflicts(data.activities,state.rules).pairs.length};}}];for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
init();
